import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { getProductos, addProducto, updateProducto, deleteProducto, getAdminPedidos } from '../services/api';
import './EstiloInicio.css'; // Reutilizamos estilos base
import './EstiloSesiones.css'; // Para modales y formularios

const AdminDashboard = () => {
    const [productos, setProductos] = useState([]);
    const [pedidos, setPedidos] = useState([]);
    const [vista, setVista] = useState('productos'); // 'productos' o 'pedidos'
    const [modalProducto, setModalProducto] = useState(null); // null o { product data }
    const [error, setError] = useState('');
    const navigate = useNavigate();

    useEffect(() => {
        // Verificar si es admin al cargar
        const usuario = JSON.parse(localStorage.getItem('usuario'));
        if (!usuario || usuario.tipo !== 'admin') {
            navigate('/home');
        }
        cargarDatos();
    }, [navigate]);

    const cargarDatos = async () => {
        try {
            const prodData = await getProductos();
            setProductos(prodData.data || prodData);
            const pedData = await getAdminPedidos();
            setPedidos(pedData.data || pedData);
        } catch (err) {
            setError('Error cargando datos: ' + err.message);
        }
    };

    const handleSaveProducto = async (e) => {
        e.preventDefault();
        const formData = new FormData(e.target);
        const data = Object.fromEntries(formData.entries());

        try {
            if (modalProducto.id) {
                await updateProducto(modalProducto.id, data);
            } else {
                await addProducto(data);
            }
            setModalProducto(null);
            cargarDatos();
        } catch (err) {
            setError('Error al guardar: ' + err.message);
        }
    };

    const handleDelete = async (id) => {
        if (window.confirm('¿Estás seguro de desactivar este producto?')) {
            try {
                await deleteProducto(id);
                cargarDatos();
            } catch (err) {
                setError('Error al eliminar: ' + err.message);
            }
        }
    };

    return (
        <div className="App" style={{ minHeight: '100vh', background: 'linear-gradient(135deg, #1a2a6c, #b21f1f, #fdbb2d)' }}>
            <header className="App-header">
                <div className="header-container">
                    <div className="title">Panel Admin - CafES</div>
                    <button className="sesion_regis" style={{ padding: '5px 15px' }} onClick={() => navigate('/home')}>Volver</button>
                </div>
            </header>

            <main className="App-main" style={{ padding: '20px' }}>
                <div className="tabs-container mb-4" style={{ display: 'flex', gap: '10px', justifyContent: 'center' }}>
                    <button className={`sesion_inicio ${vista === 'productos' ? 'active-tab' : ''}`} onClick={() => setVista('productos')}>Productos</button>
                    <button className={`sesion_inicio ${vista === 'pedidos' ? 'active-tab' : ''}`} onClick={() => setVista('pedidos')}>Pedidos</button>
                </div>

                {error && <div className="alert alert-danger">{error}</div>}

                {vista === 'productos' && (
                    <div className="glass-panel p-4" style={{ background: 'rgba(255,255,255,0.1)', backdropFilter: 'blur(10px)', borderRadius: '15px', color: 'white' }}>
                        <div className="d-flex justify-content-between mb-3">
                            <h3>Gestión de Productos</h3>
                            <button className="btn btn-success" onClick={() => setModalProducto({ nombre: '', precio: 0, descripcion: '', categoria_id: 1 })}>+ Nuevo Producto</button>
                        </div>
                        <table className="table table-dark table-hover">
                            <thead>
                                <tr>
                                    <th>Nombre</th>
                                    <th>Precio</th>
                                    <th>Estado</th>
                                    <th>Acciones</th>
                                </tr>
                            </thead>
                            <tbody>
                                {productos.map(p => (
                                    <tr key={p.id}>
                                        <td>{p.nombre}</td>
                                        <td>{p.precio}€</td>
                                        <td>{p.activo ? '✅' : '❌'}</td>
                                        <td>
                                            <button className="btn btn-sm btn-primary me-2" onClick={() => setModalProducto(p)}>Editar</button>
                                            <button className="btn btn-sm btn-danger" onClick={() => handleDelete(p.id)}>Desactivar</button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}

                {vista === 'pedidos' && (
                    <div className="glass-panel p-4" style={{ background: 'rgba(255,255,255,0.1)', backdropFilter: 'blur(10px)', borderRadius: '15px', color: 'white' }}>
                        <h3>Historial de Pedidos (Global)</h3>
                        <table className="table table-dark table-hover">
                            <thead>
                                <tr>
                                    <th>ID</th>
                                    <th>Usuario</th>
                                    <th>Fecha</th>
                                    <th>Total</th>
                                    <th>Estado</th>
                                </tr>
                            </thead>
                            <tbody>
                                {pedidos.map(p => (
                                    <tr key={p.id}>
                                        <td>#{p.id}</td>
                                        <td>{p.usuario_nombre}</td>
                                        <td>{new Date(p.fecha).toLocaleString()}</td>
                                        <td>{p.total}€</td>
                                        <td>{p.estado}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}

                {modalProducto && (
                    <div className="prefs-overlay">
                        <div className="prefs-modal shadow-lg" style={{ maxWidth: '500px' }}>
                            <h3>{modalProducto.id ? 'Editar Producto' : 'Nuevo Producto'}</h3>
                            <form onSubmit={handleSaveProducto}>
                                <div className="mb-3">
                                    <label>Nombre</label>
                                    <input type="text" name="nombre" className="form-control" defaultValue={modalProducto.nombre} required />
                                </div>
                                <div className="mb-3">
                                    <label>Precio</label>
                                    <input type="number" step="0.01" name="precio" className="form-control" defaultValue={modalProducto.precio} required />
                                </div>
                                <div className="mb-3">
                                    <label>Descripción</label>
                                    <textarea name="descripcion" className="form-control" defaultValue={modalProducto.descripcion}></textarea>
                                </div>
                                <div className="mb-3">
                                    <label>Categoría ID</label>
                                    <input type="number" name="categoria_id" className="form-control" defaultValue={modalProducto.categoria_id} required />
                                </div>
                                <div className="d-flex gap-2">
                                    <button type="submit" className="btn-confirm-prefs">Guardar</button>
                                    <button type="button" className="btn btn-secondary" onClick={() => setModalProducto(null)}>Cancelar</button>
                                </div>
                            </form>
                        </div>
                    </div>
                )}
            </main>
        </div>
    );
};

export default AdminDashboard;
